// 1. Define the Custom Error
class ValidationError extends Error {
  constructor(message) {
    super(message); // Call the parent Error constructor
    this.name = "ValidationError";
  }
}

// 2. Use it in your business logic
function registerUser(age) {
  if (age < 18) {
    throw new ValidationError("User must be at least 18.");
  }
  return "Success";
}

// 3. Catch and inspect it
try {
  registerUser(15);
} catch (error) {
  if (error instanceof ValidationError) {
    console.log("Show popup to user:", error.message);
  } else {
    console.log("Fatal system crash! Send to Sentry.", error);
  }
}
